insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_tt2_v1'
from (values
('117.324.c.1.A',2,'A crew member asks for a ''cyc'' to be lit blue for a sky effect. The cyc is a ___.','["Large smooth backdrop at the back of the stage", "Kind of ticket", "Type of wig", "Tool for cutting fabric"]'::jsonb,0,'A cyclorama is a stage backdrop.','original'),
('117.324.c.1.A',2,'In makeup vocabulary, ''contouring'' means ___.','["Gluing on a wig", "Using light and dark shades to shape the face", "Removing all makeup", "Printing a program"]'::jsonb,1,'Contouring shapes features.','original'),
('117.324.c.1.B',2,'The area of the stage to the audience''s left of center is ___ when facing the audience from the actor''s view.','["Upstage", "Offstage", "Actor''s right", "Downstage"]'::jsonb,2,'Stage left and right are from the actor''s view.','original'),
('117.324.c.1.B',2,'The grid is the structure that ___.','["Seats the audience", "Holds the costumes", "Houses the ticket booth", "Supports the rigging and lines above the stage"]'::jsonb,3,'The grid carries overhead loads.','original'),
('117.324.c.1.C',2,'A production meeting is used so that ___.','["Designers, directors and managers share progress and solve problems", "Actors audition", "Ticket buyers choose seats", "Crew members take breaks"]'::jsonb,0,'Meetings coordinate departments.','original'),
('117.324.c.1.C',2,'What is the purpose of ''load-in''?','["Selling snacks", "Bringing scenery, lights and equipment into the theatre to prepare for tech", "Writing the review", "Casting the show"]'::jsonb,1,'Load-in readies the venue.','original'),
('117.324.c.1.D',2,'Which shop practice improves safety?','["Leaving blades out", "Running in the shop", "Keeping the floor clear of sawdust and cords", "Horseplay with tools"]'::jsonb,2,'A tidy shop prevents accidents.','original'),
('117.324.c.1.D',2,'If a fire alarm sounds during rehearsal, what should students do?','["Hide backstage", "Go back for belongings", "Finish the scene", "Leave by the posted exit route and gather at the meeting place"]'::jsonb,3,'Follow evacuation procedures.','original'),
('117.324.c.1.E',3,'A student reads a script and marks every costume change with the page number. She is analyzing ___.','["Technical needs for the wardrobe department", "Press reviews", "Parking", "Seat prices"]'::jsonb,0,'Script analysis identifies requirements.','original'),
('117.324.c.1.E',3,'A stage direction says ''Thunder rumbles.'' Which department is most affected?','["Properties", "Sound", "Makeup", "Costumes"]'::jsonb,1,'Thunder is a sound cue.','original'),
('117.324.c.2.A',3,'A realistic kitchen set and a minimalist dance set use technical elements differently. This reflects ___.','["Seat numbers", "Ticket color", "Differences in theatrical style", "Weather"]'::jsonb,2,'Styles shape design choices.','original'),
('117.324.c.2.A',3,'For a comedy with quick entrances, which scenic choice helps?','["No exits", "Heavy locked doors", "Windows only", "Doors that open easily and have clear sightlines"]'::jsonb,3,'Comedy needs practical movement.','original'),
('117.324.c.2.B',3,'When applying the design process, what step follows analysis?','["Research", "Opening night", "Strike", "Curtain call"]'::jsonb,0,'Analysis then research.','original'),
('117.324.c.2.B',3,'What is the last step of the design process?','["Research", "Evaluation", "Incubation", "Analysis"]'::jsonb,1,'Designers review the result at the end.','original'),
('117.324.c.2.C',3,'Which is a principle of design that deals with how heavy or light something looks on stage?','["Tempo", "Applause", "Mass", "Echo"]'::jsonb,2,'Mass describes visual weight.','original'),
('117.324.c.2.C',3,'A diagonal line on stage often suggests ___.','["Absence", "Silence", "Calm rest", "Movement or tension"]'::jsonb,3,'Diagonals add energy.','original'),
('117.324.c.2.D',3,'A designer repeats a color and shape throughout a set to create ___.','["Unity", "Contrast only", "Silence", "Chaos"]'::jsonb,0,'Repetition builds unity.','original'),
('117.324.c.2.D',3,'A design that uses very different textures side by side shows ___.','["Harmony", "Contrast", "Repetition", "Unity"]'::jsonb,1,'Opposites create contrast.','original'),
('117.324.c.2.E',3,'Mixing red and green light on a white wall will give what color of light, in additive color mixing?','["Black", "Purple", "Yellow", "Orange"]'::jsonb,2,'Red + green light = yellow.','original'),
('117.324.c.2.E',3,'Warm colors on stage often suggest ___.','["Cold distance", "Absence", "Silence", "Comfort or energy"]'::jsonb,3,'Warm hues feel inviting.','original'),
('117.324.c.2.F',3,'A director asks for a ''cold, lonely'' lighting mood. A lighting designer responds with ___.','["Cool blues and low angles", "Bright white everywhere", "No light at all", "Warm amber glow"]'::jsonb,0,'Designers translate mood into tools.','original'),
('117.324.c.2.F',3,'What is a costume rendering used for?','["To sell tickets", "To show the director the design of a costume", "To mix sound", "To measure lumber"]'::jsonb,1,'Renderings communicate designs.','original'),
('117.324.c.2.G',3,'A scale model uses 1/2 inch to represent 1 foot. A wall 10 feet tall will measure ___ in the model.','["2 inches", "10 inches", "5 inches", "20 inches"]'::jsonb,2,'10 × 1/2 = 5.','original'),
('117.324.c.2.G',3,'A drafter draws a 12-foot platform at a scale of 1/4 inch = 1 foot. How long is the drawing?','["1 inch", "12 inches", "6 inches", "3 inches"]'::jsonb,3,'12 × 1/4 = 3.','original'),
('117.324.c.3.A',2,'Before operating the drill press, a student should ___.','["Secure the work piece and wear safety glasses", "Remove the guard", "Work in loose clothing", "Hold the piece by hand"]'::jsonb,0,'Clamps and PPE prevent injury.','original'),
('117.324.c.3.A',2,'Who may use a table saw in the school shop?','["Anyone", "Trained students with permission from the teacher", "New students on their first day", "Visitors"]'::jsonb,1,'Training and approval are required.','original'),
('117.324.c.3.C',3,'A light plot shows ___.','["The ticket sales", "The cast list", "Where each lighting instrument is hung and aimed", "The menu"]'::jsonb,2,'A plot maps instruments.','original'),
('117.324.c.3.C',3,'A costume plot lists ___.','["Sound cues only", "Seats", "Lighting levels", "Which characters wear which costumes in each scene"]'::jsonb,3,'It tracks costume use.','original'),
('117.324.c.3.B.i',3,'A flat is made from a wooden frame covered with ___.','["Muslin or thin plywood", "Metal foil only", "Water", "Candy wrappers"]'::jsonb,0,'Flats are covered with fabric or plywood.','original'),
('117.324.c.3.B.i',3,'To build stairs for a set, a student must ensure ___.','["They are glued with paste only", "Rise and run are equal for every step", "Every step is a different height", "No supports are used"]'::jsonb,1,'Equal rises prevent tripping.','original'),
('117.324.c.3.B.ii',3,'Before altering a costume, a crew member should ___.','["Use scissors on the actor", "Skip the fitting", "Take measurements and pin the changes while the actor wears it carefully", "Cut without measuring"]'::jsonb,2,'Fittings prevent errors.','original'),
('117.324.c.3.B.ii',3,'A seam allowance is ___.','["A wig style", "A color of thread", "A type of dye", "Extra fabric between the stitch line and the cut edge"]'::jsonb,3,'Seam allowance allows for finishing.','original'),
('117.324.c.3.B.iii',3,'After hanging a light, the next step is to ___.','["Focus it by aiming and adjusting the shutters and beam", "Bury it", "Paint it", "Hide it"]'::jsonb,0,'Focus aims and shapes the light.','original'),
('117.324.c.3.B.iii',3,'A lighting controller is used to ___.','["Mix paints", "Set and change the levels of the instruments", "Measure lumber", "Seat audience members"]'::jsonb,1,'Controllers operate lights.','original'),
('117.324.c.3.B.iv',3,'The unit used to measure electrical current is the ___.','["Volt", "Ohm", "Ampere", "Watt"]'::jsonb,2,'Current is measured in amperes.','original'),
('117.324.c.3.B.iv',3,'What does a circuit breaker do?','["Counts tickets", "Makes sound", "Colors the beam", "Stops current if the circuit is overloaded"]'::jsonb,3,'Breakers protect from overload.','original'),
('117.324.c.3.B.v',3,'A sound designer records a door slam using a microphone. She is ___ a sound effect.','["Creating", "Selling", "Burying", "Cutting a costume for"]'::jsonb,0,'Recording makes effects.','original'),
('117.324.c.3.B.v',3,'Editing a sound effect to make it shorter involves ___.','["Moving the stage", "Trimming the audio file", "Adding paint", "Cutting the cable"]'::jsonb,1,'Editing changes length.','original'),
('117.324.c.3.B.vi',2,'Which is a marketing product for a school play?','["Clamp", "Ladder", "Poster or program", "Saw"]'::jsonb,2,'Posters and programs promote shows.','original'),
('117.324.c.3.B.vi',2,'Why do theatres use social media posts to market a show?','["To build scenery", "To hide the show", "To hire actors", "To reach audiences and sell tickets"]'::jsonb,3,'Marketing attracts audiences.','original'),
('117.324.c.3.B.vii',3,'A promptbook is built by ___.','["Collecting script pages with blocking, cues and notes in one place", "Ordering supplies", "Selling tickets", "Painting walls"]'::jsonb,0,'The promptbook guides the show.','original'),
('117.324.c.3.B.vii',3,'When the stage manager says ''Standby light cue 12,'' she is ___.','["Calling a break", "Warning the operator that the cue is coming", "Starting intermission", "Ending the show"]'::jsonb,1,'Standbys prepare for cues.','original'),
('117.324.c.3.B.viii',3,'In scenic painting, ''dry brushing'' is used to ___.','["Clean a brush with water", "Soak the flat", "Add texture by lightly dragging a brush with little paint", "Mix colors with a hammer"]'::jsonb,2,'Dry brushing adds texture.','original'),
('117.324.c.3.B.viii',3,'A base coat on a flat is used to ___.','["Hide the script", "Make it louder", "Make it heavier", "Cover the surface before adding details"]'::jsonb,3,'A base coat prepares the surface.','original'),
('117.324.c.3.B.ix',3,'The property master may ''buy, borrow or build'' an item. Which is an example of borrowing?','["Asking a community member to lend a rocking chair for the run", "Purchasing a new chair", "Painting a flat", "Sewing a chair"]'::jsonb,0,'Borrowing means loaning.','original'),
('117.324.c.3.B.ix',3,'Why is a props table organized by scene?','["To cut the show", "So actors and crew can find items quickly", "To hide the props", "To confuse the cast"]'::jsonb,1,'Organization speeds changes.','original'),
('117.324.c.4.A',3,'A designer studying Victorian homes adds detailed wallpaper and furniture to the set. She is applying ___.','["Randomness", "Guesswork", "Historical accuracy from research", "Rule breaking"]'::jsonb,2,'Research informs details.','original'),
('117.324.c.4.A',3,'When designing for a play set in a particular culture, what should a designer do first?','["Ignore the setting", "Copy a cartoon", "Guess", "Research authentic clothing, architecture and symbols"]'::jsonb,3,'Authenticity needs research.','original'),
('117.324.c.4.B',3,'A film can show multiple locations through editing. A stage design typically solves location changes with ___.','["Scenery, lighting and transitions", "Sound alone", "Printed maps", "Cuts to different cameras"]'::jsonb,0,'Stages use scenic transitions.','original'),
('117.324.c.4.B',3,'Which statement describes the influence of television on live theatre?','["Actors stopped speaking", "Audiences expect polished visuals and sound", "Theatre disappeared", "Audiences dislike stories"]'::jsonb,1,'Media raised expectations.','original'),
('117.324.c.4.C',3,'Japanese Kabuki and Noh theatre show the ___ of world theatre.','["Cost", "Parking", "Cultural heritage", "Weather"]'::jsonb,2,'They are major traditions.','original'),
('117.324.c.4.C',3,'Which ancient playwright wrote tragedies such as ''Oedipus Rex''?','["Picasso", "Edison", "Mozart", "Sophocles"]'::jsonb,3,'Sophocles is a Greek tragedian.','original'),
('117.324.c.4.D',3,'Which theatre building style was introduced during the Renaissance, featuring a frame around the stage?','["Proscenium", "Arena", "Longhouse", "Amphitheater"]'::jsonb,0,'Proscenium theatres frame the stage.','original'),
('117.324.c.4.D',3,'Greek theatres were built into hillsides in a shape called a(n) ___.','["Booth", "Amphitheater", "Atrium", "Hangar"]'::jsonb,1,'Hillsides provided seating.','original'),
('117.324.c.4.E',3,'Early stage lighting used candles and oil lamps. Later, theatres adopted gas and then ___.','["Mirrors only", "Fireworks", "Electric lighting", "Torches only"]'::jsonb,2,'Technology progressed to electric.','original'),
('117.324.c.4.E',3,'LED instruments have changed theatre because they ___.','["Need candles", "Burn hotter", "Are silent", "Use less energy and can change colors easily"]'::jsonb,3,'LED technology is efficient and flexible.','original'),
('117.324.c.4.F',3,'American theatre has been shaped by many cultures, including African American, Latino and Native American playwrights. This is the ___ heritage of US theatre.','["Multicultural", "Single", "Foreign only", "Imaginary"]'::jsonb,0,'U.S. theatre reflects many cultures.','original'),
('117.324.c.4.F',3,'Which playwright is known for writing ''A Raisin in the Sun''?','["Neil Simon", "Lorraine Hansberry", "Arthur Miller", "Tennessee Williams"]'::jsonb,1,'Hansberry wrote this play.','original'),
('117.324.c.4.G',3,'Which US innovation helped lighting designers control many lights at once?','["Torch lines", "Candle chandeliers", "Computerized dimmer boards", "Hand mirrors"]'::jsonb,2,'Computer boards enabled complex cueing.','original'),
('117.324.c.4.G',3,'The United States is credited with developing which form that combines song, dance and story?','["Greek chorus", "Commedia dell''arte", "Noh", "The musical"]'::jsonb,3,'The musical grew in America.','original'),
('117.324.c.5.A',2,'A resume for technical theatre should include ___.','["Productions worked on, roles held and skills learned", "Lunch menu", "Favorite color", "Pet names"]'::jsonb,0,'Resumes list relevant experience.','original'),
('117.324.c.5.A',2,'A portfolio of technical theatre works may include ___.','["Only programs from other schools", "Photos of finished sets, drawings and light plots", "Only receipts", "Only tickets"]'::jsonb,1,'Portfolios show work.','original'),
('117.324.c.5.B',2,'A crew member on headset during a show should ___.','["Turn the volume to loud", "Chat constantly", "Speak only when needed and keep chatter off the line", "Sing along"]'::jsonb,2,'Quiet headset discipline.','original'),
('117.324.c.5.B',2,'What should a backstage crew member wear during a show?','["Flip-flops", "Noisy shoes", "Bright costumes", "Dark, quiet clothing and closed-toe shoes"]'::jsonb,3,'Backstage attire is quiet and safe.','original'),
('117.324.c.5.C',3,'A student reflects that her sound design added tension to a scene. She is evaluating her work as ___.','["Art that affects the audience", "A rule violation", "Random noise", "Scrap"]'::jsonb,0,'Design is an art form.','original'),
('117.324.c.5.C',3,'Self-evaluation in technical theatre includes ___.','["Blaming others", "Looking at what worked, what failed and how to improve", "Praising only", "Ignoring results"]'::jsonb,1,'Reflection builds skill.','original'),
('117.324.c.5.D',3,'A peer says: ''Your color palette is cohesive, but the platform edges look unfinished.'' This is ___.','["Spam", "A rumor", "Constructive criticism", "An insult"]'::jsonb,2,'Specific and helpful.','original'),
('117.324.c.5.D',3,'When someone critiques your design, you should ___.','["Argue", "Ignore", "Interrupt", "Listen, ask questions and consider changes"]'::jsonb,3,'Open reception improves work.','original'),
('117.324.c.5.E',3,'A reviewer writes that a lighting change at the climax focused attention on the actor. This is ___ evaluation.','["Specific", "Vague", "Silent", "Unrelated"]'::jsonb,0,'Specific details support evaluation.','original'),
('117.324.c.5.E',3,'Which describes a precise comment on a play''s scenery?','["It was a set", "The revolving set shifted smoothly between the home and the office", "Looked fine", "Pretty"]'::jsonb,1,'Precision names effect.','original'),
('117.324.c.5.F',3,'A student compares the camera work in a film to the staging in a play. She is evaluating ___.','["The weather", "The ticket color", "Different media", "The parking"]'::jsonb,2,'Different media use different tools.','original'),
('117.324.c.5.F',3,'Which is a precise comment on a TV show''s costumes?','["They wore clothes", "Fine", "Looked nice", "The muted colors matched the gloomy tone of the story"]'::jsonb,3,'Detailed observation.','original'),
('117.324.c.5.G',3,'A student interested in sound might explore a career as ___.','["Audio engineer in theatre or film", "Chef", "Surveyor", "Pilot"]'::jsonb,0,'Audio careers exist in several media.','original'),
('117.324.c.5.G',3,'Which place hires scenic carpenters besides theatres?','["Banks only", "Film studios and theme parks", "Libraries only", "Weather stations only"]'::jsonb,1,'Industries use scenic skills.','original'),
('117.324.c.5.H',3,'Time management learned in technical theatre helps students in ___.','["Only drama class", "Only shows", "College and other careers", "Nothing"]'::jsonb,2,'Skills transfer.','original'),
('117.324.c.5.H',3,'A student explains that problem solving on a crew will help in engineering school. She is ___ theatre to higher education.','["Ending", "Hiding", "Rejecting", "Connecting"]'::jsonb,3,'She links experience to her future.','original'),
('117.324.c.5.I',3,'A student uses presentation software to explain how she built a staircase. She is using ___ to communicate findings.','["Technology", "A drill bit", "A hammer", "A saw"]'::jsonb,0,'Slides communicate process.','original'),
('117.324.c.5.I',3,'A coherent technical presentation has ___.','["No images", "Clear structure, labeled visuals and concise explanations", "Long unlabeled paragraphs", "Random order"]'::jsonb,1,'Organization helps audiences.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
